insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-clary-sage', 'clary-sage', 'クラリセージ', 'Salvia sclarea', 'シソ科', 'ミドル', 'ハーバル、甘い、ややナッティ', '落ち着いた甘さのあるハーブ調。夜やくつろぎのブレンドに深みを加えます。', '["落ち着きたい時","フローラルの調整","大人っぽい香り"]', '["relax","sleep"]', '["ベルガモット","ラベンダー","ゼラニウム","シダーウッド"]', '妊娠中や飲酒時などは使用を控える判断が必要です。', '#b8a6c8'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-cedarwood', 'cedarwood', 'シダーウッド', 'Cedrus atlantica', 'マツ科', 'ベース', 'ウッディ、乾いた木、落ち着き', '穏やかな木の香り。ブレンドに安定感を出し、甘い香りを引き締めます。', '["夜の落ち着き","ウッディ調","香りの土台づくり"]', '["relax","sleep","focus"]', '["オレンジ","ラベンダー","ローズマリー","フランキンセンス"]', '重くなりやすいので、トップノートと合わせて少量から調整してください。', '#b89068'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-sandalwood', 'sandalwood', 'サンダルウッド', 'Santalum album', 'ビャクダン科', 'ベース', 'なめらか、ウッディ、クリーミー', 'なめらかで静かな木の香り。余韻が長く、瞑想的なブレンドや高級感の演出に向きます。', '["深いリラックス","香りの余韻","高級感のあるブレンド"]', '["relax","sleep"]', '["フランキンセンス","イランイラン","ベルガモット","ローズ"]', '希少性が高い精油です。由来や品質表示を確認してください。', '#c0a076'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-patchouli', 'patchouli', 'パチュリ', 'Pogostemon cablin', 'シソ科', 'ベース', '土っぽい、甘い、重厚', '個性的で深い土っぽさのある香り。少量でブレンドに奥行きと持続性を加えます。', '["香りの固定","落ち着いた印象","個性的なブレンド"]', '["relax"]', '["ゼラニウム","ベルガモット","サンダルウッド","クラリセージ"]', '非常に存在感が強いため、1滴未満の感覚で少量から調整してください。', '#9b7b5b'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-grapefruit', 'grapefruit', 'グレープフルーツ', 'Citrus paradisi', 'ミカン科', 'トップ', 'ほろ苦い柑橘、軽快、明るい', '軽やかでほろ苦い柑橘の香り。朝や気分転換のブレンドにフレッシュさを足します。', '["朝の気分転換","軽やかな柑橘","リフレッシュ"]', '["energy","happy","refresh"]', '["ローズマリー","ペパーミント","ジュニパーベリー","ゼラニウム"]', '圧搾グレープフルーツは光毒性に注意が必要です。肌使用時は確認してください。', '#f2bf7a'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-lime', 'lime', 'ライム', 'Citrus aurantifolia', 'ミカン科', 'トップ', '鋭い柑橘、爽快、軽い甘さ', 'キレのある爽快な柑橘。甘い香りを軽くしたい時や、リフレッシュ感を出す時に使いやすい精油です。', '["リフレッシュ","明るい印象づくり","甘さの調整"]', '["energy","happy","refresh"]', '["ペパーミント","ジンジャー","レモングラス","シダーウッド"]', '圧搾ライムは光毒性に注意。蒸留品など製品仕様を確認してください。', '#c9d86f'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-mandarin', 'mandarin', 'マンダリン', 'Citrus reticulata', 'ミカン科', 'トップ', 'やさしい柑橘、甘い、軽い', '甘くやさしい柑橘の香り。強い香りが苦手な人にも使いやすく、夜の柑橘ブレンドにも向きます。', '["穏やかな気分転換","家族向けの空間","やさしい甘さ"]', '["relax","happy"]', '["ラベンダー","カモミール","ネロリ","フランキンセンス"]', '柑橘精油として、肌使用時は製品の光毒性情報を確認してください。', '#f0b66f'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-lemongrass', 'lemongrass', 'レモングラス', 'Cymbopogon citratus', 'イネ科', 'トップ', 'レモン様、草、力強い', 'レモンに似た強い草の香り。空間をすっきりさせたい時に少量使うと印象が変わります。', '["リフレッシュ","空間の切り替え","シャープな印象"]', '["refresh","energy"]', '["ライム","ジンジャー","ペパーミント","シダーウッド"]', '刺激が強めです。肌使用では低濃度にし、敏感肌は注意してください。', '#c6ca72'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-chamomile-roman', 'chamomile-roman', 'ローマンカモミール', 'Chamaemelum nobile', 'キク科', 'ミドル', 'リンゴ様、甘い、穏やか', '甘くやさしいハーブ調。夜のリラックスブレンドに丸みを与えます。', '["就寝前","穏やかな香り","やさしいハーブ調"]', '["relax","sleep"]', '["ラベンダー","マンダリン","クラリセージ","サンダルウッド"]', 'キク科に敏感な方は注意してください。', '#e8d799'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-rose', 'rose', 'ローズ', 'Rosa damascena', 'バラ科', 'ミドル', '華やか、濃厚、上品', '少量で華やかさが出る高級感のある香り。フローラルブレンドの印象を大きく変えます。', '["特別感のある香り","気分を上げたい時","フローラルの主役"]', '["happy","relax"]', '["サンダルウッド","ベルガモット","ゼラニウム","ネロリ"]', '高価で濃厚な香りです。少量から使い、品質表示を確認してください。', '#df9aae'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-neroli', 'neroli', 'ネロリ', 'Citrus aurantium var. amara', 'ミカン科', 'ミドル', '白い花、柑橘、上品', 'ビターオレンジの花から得られる上品な香り。落ち着きと明るさを両立したいブレンドに合います。', '["夜のケア時間","上品なフローラル","気分の切り替え"]', '["relax","happy"]', '["ラベンダー","ベルガモット","サンダルウッド","マンダリン"]', '香りが繊細なので、強い精油と合わせる時は量を控えめにしてください。', '#f2d7bc'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-jasmine', 'jasmine', 'ジャスミン', 'Jasminum grandiflorum', 'モクセイ科', 'ミドル', '濃厚な花、甘い、官能的', '甘く濃厚な白花の香り。ごく少量で華やかさと深みを加えます。', '["気分を上げたい時","特別なブレンド","甘いフローラル"]', '["happy","relax"]', '["ベルガモット","サンダルウッド","ローズ","オレンジ"]', '強く香るため少量から調整してください。妊娠中などは専門家に確認してください。', '#e7c0d2'); insert into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-palmarosa', 'palmarosa', 'パルマローザ', 'Cymbopogon martinii', 'イネ科', 'ミドル', 'ローズ調、草、軽い甘さ', 'ローズに似た明るい草花の香り。フローラルを軽くしたい時に使いやすい精油です。', '["バランスの良い香り","軽いフローラル","気分転換"]', '["relax","happy"]', '["ゼラニウム","ラベンダー","ベルガモット","シダーウッド"]', '香りが広がりやすいため、少量から調整してください。', '#d9b4a8');
